#:property AllowUnsafeBlocks=true

Console.WriteLine($"IntPtr.Size = {IntPtr.Size} bytes ({IntPtr.Size * 8}-bit platform)");

// stackalloc nint (signed native-sized integer)
Span<nint> signed = stackalloc nint[4];
for (int i = 0; i < signed.Length; i++)
    signed[i] = i * 10;

Console.WriteLine("\nSpan<nint> via stackalloc:");
for (int i = 0; i < signed.Length; i++)
    Console.WriteLine($"  [{i}] = {signed[i]}");

// stackalloc nuint (unsigned native-sized integer)
Span<nuint> unsigned = stackalloc nuint[4];
for (int i = 0; i < unsigned.Length; i++)
    unsigned[i] = (nuint)(i * 100);

Console.WriteLine("\nSpan<nuint> via stackalloc:");
for (int i = 0; i < unsigned.Length; i++)
    Console.WriteLine($"  [{i}] = {unsigned[i]}");

Console.WriteLine("\n✅ stackalloc Span<nint> and Span<nuint> both work!");

